import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:]]

    sheet = defaultdict(bool)
    count = 0

    for x in a:
        if sheet[x]:
            sheet[x] = False
            count -= 1
        else:
            sheet[x] = True
            count += 1

    print(count)

if __name__ == "__main__":
    solve()

import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    # Count occurrences of each number
    counts = Counter()
    for _ in range(n):
        try:
            val = int(next(iterator))
            counts[val] += 1
        except StopIteration:
            break

    # A number remains on the sheet if it appears an odd number of times
    result = sum(1 for count in counts.values() if count % 2 == 1)
    print(result)

if __name__ == "__main__":
    solve()

